import{useId}from'react';
import{legacy2019InspectionSource as s,legacy2019InspectionProfiles,legacy2019InspectionFigureAlt}from'../../src/core/generators/legacy-2019-pm-inspection-model';
/** Year-only managed media. No invented FK lines or answer helper edges. */
export function Legacy2019InspectionFigure({profile,values,caption}:{profile:string;values:number[];caption:string}){
 const id=useId().replace(/:/g,'');if(!legacy2019InspectionProfiles.includes(profile)||values.length!==1||values[0]!==0)throw Error('PARAMETER_CONSTRAINT');
 const name=profile.replace('legacy-2019-inspection-',''),alt=legacy2019InspectionFigureAlt(name);
 if(name==='api-table')return <figure className={'managed-diagram source-figure profile-'+profile}><div className="table-scroll" tabIndex={0} aria-label="情報取得用WebAPIの説明。幅が足りない場合は左右へスクロールできます。"><table style={{minWidth:1100}}><caption>{caption}</caption><colgroup>{[170,230,80,620].map((w,i)=><col key={i} style={{width:w}}/>)}</colgroup><thead><tr><th scope="col"><span className="table-heading-text">サーバ</span></th><th scope="col"><span className="table-heading-text">WebAPI名</span></th><th scope="col" colSpan={2}><span className="table-heading-text">WebAPI仕様</span></th></tr></thead><tbody>{s.apis.flatMap((a,i)=>['引数','戻り値','処理'].map((label,j)=><tr key={a.name+'-'+j}>{j===0&&(i===0||i===4)&&<th scope="rowgroup" rowSpan={i===0?12:9}><span className="table-heading-text">{a.server}</span></th>}{j===0&&<th scope="rowgroup" rowSpan={3}><span className="table-heading-text">{a.name}</span></th>}<th scope="row"><span className="table-heading-text">{label}</span></th><td>{j===0?a.args.join('、'):j===1?a.returns:a.processing}</td></tr>))}</tbody></table></div><p>{s.table1.note}</p></figure>;
 if(name==='product-report'){const f=s.page27.figure3;return <figure className={'managed-diagram source-figure profile-'+profile}><div className="table-scroll" tabIndex={0} aria-label="農産物検査結果の表示例。幅が足りない場合は左右へスクロールできます。"><p>申込者情報・検査農産物情報</p><dl style={{minWidth:780}}><dt>検査農産物ID</dt><dd><span className="table-cell-value">{f.productId}</span></dd><dt>検査農産物名</dt><dd>{f.productName}</dd>{Object.entries(f.offerer).map(([k,v])=><div key={k}><dt>{k}</dt><dd>{v}</dd></div>)}</dl><p>検査結果情報</p><table style={{minWidth:780}}><caption>{caption}</caption><colgroup>{[60,190,170,170,190].map((w,i)=><col key={i} style={{width:w}}/>)}</colgroup><thead><tr><th scope="col" aria-label="行番号"></th>{f.columns.map(c=><th key={c} scope="col"><span className="table-heading-text">{c}</span></th>)}</tr></thead><tbody>{f.rows.map((row,i)=><tr key={i}><th scope="row"><span className="table-heading-text">{i+1}</span></th>{row.map((v,j)=><td key={j}>{v&&<span className={j===0||j===3||/^\d/.test(v)?'table-cell-value':undefined}>{v}</span>}</td>)}</tr>)}</tbody></table></div></figure>;}
 if(name==='results-list'){const f=s.page28and29.figure4;return <figure className={'managed-diagram source-figure profile-'+profile}><p>{f.startLabel}　前へ　次へ</p><div className="table-scroll" tabIndex={0} aria-label="検査結果リストの表示例。幅が足りない場合は左右へスクロールできます。"><table style={{minWidth:1050}}><caption>{caption}</caption><colgroup>{[60,160,190,180,140,150,170].map((w,i)=><col key={i} style={{width:w}}/>)}</colgroup><thead><tr>{f.columns.map(c=><th key={c} scope="col"><span className="table-heading-text">{c}</span></th>)}</tr></thead><tbody>{Array.from({length:10},(_,i)=><tr key={i}>{(i===0?[...f.firstRow]:[String(i+1),...Array<string>(6).fill('⋮')]).map((v,j)=>j===0?<th key={j} scope="row"><span className="table-heading-text">{v}</span></th>:<td key={j}><span className={i===0&&[2,3,6].includes(j)?'table-cell-value':undefined}>{v}</span></td>)}</tr>)}</tbody></table></div><p>{f.note}</p></figure>;}
 const width=name==='architecture'?1360:1460,height=name==='architecture'?660:430,servers=s.page24.figure1.servers,edges=[['申込情報登録ツール','申込情報管理サーバ','M220 90V150'],['利用者情報登録ツール','認証サーバ','M660 90V150'],['検査結果登録ツール','検査結果管理サーバ','M1100 90V150'],['報告用アプリケーション','申込情報管理サーバ.情報取得用WebAPI','M530 480V430H220V350'],['報告用アプリケーション','認証サーバ.認証関連WebAPI','M660 480V350'],['報告用アプリケーション','検査結果管理サーバ.情報取得用WebAPI','M850 480V430H1100V350'],['申込情報管理サーバ.情報取得用WebAPI','認証サーバ.認証関連WebAPI','M220 350V390H580V350'],['検査結果管理サーバ.情報取得用WebAPI','認証サーバ.認証関連WebAPI','M1100 350V390H760V350']];
 return <figure className={'managed-diagram source-figure profile-'+profile}><div className="diagram-scroll" tabIndex={0} aria-label="図。幅が足りない場合は左右へスクロールできます。"><svg className="source-figure-svg" viewBox={'0 0 '+width+' '+height} style={{width:'calc('+width+'px * var(--image-scale, 1))',minWidth:'100%'}} role="img" aria-labelledby={id+'-title'} aria-describedby={id+'-desc'}><title id={id+'-title'}>{caption}</title><desc id={id+'-desc'}>{alt}</desc><defs><marker id={id+'-arrow'} viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto"><path d="M1 1L9 5L1 9" fill="none" stroke="currentColor"/></marker></defs><g aria-hidden="true" style={{fontSize:20,fontFamily:'sans-serif',fill:'none',stroke:'currentColor',strokeWidth:1.4}}>
 {name==='architecture'?<>{edges.map(([from,to,d])=><path key={from+'-'+to} data-wire-from={from} data-wire-to={to} d={d} markerEnd={'url(#'+id+'-arrow)'}/>)}{servers.map((a,i)=>{const x=20+i*440;return <g key={a.server} data-server={a.server}><rect data-box-name={a.tool} x={x} y={40} width={400} height={50}/><text x={x+200} y={68} textAnchor="middle" fill="currentColor" stroke="none">{a.tool}</text><rect data-box-name={a.server} x={x} y={150} width={400} height={210}/><text x={x+12} y={185} fill="currentColor" stroke="none">{a.server}</text><path data-db={a.db} d={'M'+(x+160)+' 220C'+(x+160)+' 203 '+(x+380)+' 203 '+(x+380)+' 220V290C'+(x+380)+' 307 '+(x+160)+' 307 '+(x+160)+' 290Z'}/><ellipse cx={x+270} cy={220} rx={110} ry={11}/><text x={x+270} y={260} textAnchor="middle" fill="currentColor" stroke="none">{a.db}</text><rect data-box-name={a.server+'.'+a.api} x={x+10} y={300} width={380} height={50}/><text x={x+200} y={328} textAnchor="middle" fill="currentColor" stroke="none">{a.api}</text></g>;})}<rect data-box-name="報告用アプリケーション" x={490} y={480} width={400} height={70}/><text x={690} y={518} textAnchor="middle" fill="currentColor" stroke="none">報告用アプリケーション</text><text x={20} y={610} fill="currentColor" stroke="none">凡例　→：アクセスを示す。記載がないアクセスは発生しない。</text></>:<>{s.page25.figure2.entities.map((e,i)=>{const x=20+i*285,h=64+e.fields.length*46;return <g key={e.name} data-entity={e.name}><rect x={x} y={25} width={260} height={h}/><line x1={x} x2={x+260} y1={80} y2={80}/><text x={x+130} y={59} textAnchor="middle" fill="currentColor" stroke="none">{e.name}</text>{e.fields.map((f,j)=><g key={f}>{f.startsWith('［')&&<rect data-blank={f} x={x+13} y={84+j*46} width={180} height={44}/>}<text data-field={e.name+':'+j} data-primary={f===e.primaryKey?'true':undefined} x={f.startsWith('［')?x+103:x+13} textAnchor={f.startsWith('［')?'middle':undefined} y={(f.startsWith('［')?109:114)+j*46} fill="currentColor" stroke="none" textDecoration={f===e.primaryKey?'underline':undefined}>{f}</text></g>)}</g>;})}<text x={20} y={380} fill="currentColor" stroke="none">{s.page25.figure2.note}</text></>}
 </g></svg></div><figcaption>{caption}</figcaption></figure>;
}
